// StayFlow - dicionario de traducao do Dashboard (painel interno,
// pos-login). Organizado por secao, com comentarios delimitando cada
// bloco pra facilitar manutencao. Cada idioma e um objeto plano (chave
// com pontos, nao aninhado - mesmo padrao ja usado na landing page).
//
// Terminologia: traducao pensada pro contexto de hotelaria (nao
// tradução literal palavra-por-palavra) - ex: "Modalidade de quarto"
// vira "Room category" em ingles (termo usado por PMS/channel manager
// de verdade), "Beliche" vira "Bunk bed", etc.

