    "onboarding.tour.promoter.performance.body": "O gráfico logo abaixo mostra a comissão gerada mês a mês - assim que suas indicações virarem clientes pagantes, o histórico aparece aqui.",
    "onboarding.tour.promoter.exploreMenu.title": "Agora explore o menu",
