    "onboarding.tour.default.welcome.title": "👋 Welcome to StayFlow",
    "onboarding.tour.default.welcome.body": "This is your Dashboard - the overview of everything happening right now. Let's quickly show you what's in each block.",
    "onboarding.tour.default.kpi.title": "Numbers at the top",
    "onboarding.tour.lodging.kpi.body": "The cards at the top show occupancy, bookings and other key numbers for the day.",
    "onboarding.tour.agency.kpi.body": "The cards at the top show a quick summary of your operation today.",
    "onboarding.tour.default.summary.title": "Executive summary",
    "onboarding.tour.default.summary.body": "A summary written by the AI, looking at the real data from your operation - so you understand the current moment without hunting through numbers one by one.",
    "onboarding.tour.lodging.opportunity.body": "Shows guests with sales potential (tour, upgrade, rental), automatically detected from conversations - so you don't leave money on the table.",
    "onboarding.tour.agency.opportunity.body": "Shows who reached out to you, automatically detected from conversations - so you don't leave money on the table.",
    "onboarding.tour.default.exploreMenu.title": "Now explore the menu",
    "onboarding.tour.default.exploreMenu.body": "The menu on the left has every area of your operation. The first time you open each one, a quick tip appears explaining what it is.",
    "onboarding.tour.promoter.welcome.title": "👋 Welcome to StayFlow",
    "onboarding.tour.promoter.welcome.body": "This is your Dashboard - the summary of your promoter account. Let's quickly show you what's in each block.",
    "onboarding.tour.promoter.numbers.title": "Your numbers",
    "onboarding.tour.promoter.numbers.body": "The 4 cards at the top show your current commission tier, how many referrals are active, how much you have to receive and how much you've already received.",
    "onboarding.tour.promoter.performance.title": "Your performance",
    "onboarding.tour.promoter.performance.body": "The chart right below shows the commission generated month by month - as soon as your referrals become paying customers, the history shows up here.",
    "onboarding.tour.promoter.exploreMenu.title": "Now explore the menu",
    "onboarding.tour.promoter.exploreMenu.body": "In the menu on the left: your referral link (Referrals), the complete statement of what you've earned (Wallet) and a ready-to-use sales guide (Sales Portfolio). The first time you open each one, a quick tip appears explaining what it is.",
    "onboarding.coach.chats.text": "Guest conversations live here. The AI replies on its own 24h - you only step in when you want to take over manually.",
    "onboarding.coach.reservations.text": "All bookings, with check-in/check-out and manual creation whenever needed.",
    "onboarding.coach.roommap.text": "A view of every room/bed: occupied, free or awaiting cleaning.",
    "onboarding.coach.opportunities.text": "When a guest asks about something sellable (a tour, a rental), the AI detects it and suggests it here - even recommending a partner if you don't sell it yourself.",
    "onboarding.coach.partners.text": "Portfolio of partner agencies you can offer to your guests.",
    "onboarding.coach.portfolio.text": "What you sell (tours, rentals) - this is what shows up for partner hostels to offer.",
    "onboarding.coach.guests.text": "Guest registry, with history and documents.",
    "onboarding.coach.operations.text": "Cleaning, maintenance and other day-to-day team tasks.",
    "onboarding.coach.team.text": "Who has access to the system and what each person can see/do.",
    "onboarding.coach.finance.text": "Charges, exchange rate and what guests have already paid.",
    "onboarding.coach.inventory.text": "Tracking of items used in the operation (linens, cleaning products, etc.).",
    "onboarding.coach.revenue.text": "Revenue over time.",
    "onboarding.coach.events.text": "Spaces and events you organize or rent out.",
    "onboarding.coach.reports.text": "Consolidated numbers for the operation.",
    "onboarding.coach.settings.text": "Hostel data, integrations, security and more.",
    "onboarding.coach.promoter.referrals.text": "Your referral link, your commission tier and the hostels you've already referred - all in this tab.",
    "onboarding.coach.promoter.wallet.text": "How much you've already earned and how much you still have to receive, month by month, with the full statement of every commission.",
    "onboarding.coach.promoter.chats.text": "Chat with anyone interested in StayFlow. To use your own WhatsApp/Facebook/Instagram here, connect it in Settings > Communication.",
    "onboarding.coach.promoter.salesportfolio.text": "A complete guide to study and pitch StayFlow in each industry - hostels, agencies, rental companies and real estate agencies.",
    "onboarding.coach.promoter.settings.text": "Connect your chat channels (WhatsApp/Facebook/Instagram) and take care of your account's security.",
