    "onboarding.coach.dismissLabel": "No mostrar más tips",
    "onboarding.coach.okBtn": "Entendido",
    "onboarding.tour.default.welcome.title": "👋 Bienvenido(a) a StayFlow",
    "onboarding.tour.default.welcome.body": "Este es tu Dashboard - la vista general de todo lo que está pasando ahora. Te mostramos rápido qué hay en cada bloque.",
    "onboarding.tour.default.kpi.title": "Números arriba",
    "onboarding.tour.lodging.kpi.body": "Las tarjetas de arriba muestran ocupación, reservas y otros números clave del día.",
    "onboarding.tour.agency.kpi.body": "Las tarjetas de arriba muestran un resumen rápido de tu operación hoy.",
    "onboarding.tour.default.summary.title": "Resumen ejecutivo",
    "onboarding.tour.default.summary.body": "Un resumen escrito por la IA, mirando los datos reales de tu operación - para que entiendas el momento sin tener que buscar número por número.",
    "onboarding.tour.lodging.opportunity.body": "Muestra huéspedes con potencial de venta (tour, upgrade, alquiler), detectado automáticamente por las conversaciones - para que no dejes plata arriba de la mesa.",
    "onboarding.tour.agency.opportunity.body": "Muestra quién te buscó, detectado automáticamente por las conversaciones - para que no dejes plata arriba de la mesa.",
    "onboarding.tour.default.exploreMenu.title": "Ahora explorá el menú",
    "onboarding.tour.default.exploreMenu.body": "En el menú de la izquierda está cada área de la operación. La primera vez que abras cada una, aparece un tip rápido explicando qué es.",
    "onboarding.tour.promoter.welcome.title": "👋 Bienvenido(a) a StayFlow",
    "onboarding.tour.promoter.welcome.body": "Este es tu Dashboard - el resumen de tu cuenta de promotor. Te mostramos rápido qué hay en cada bloque.",
    "onboarding.tour.promoter.numbers.title": "Tus números",
    "onboarding.tour.promoter.numbers.body": "Las 4 tarjetas de arriba muestran tu franja de comisión actual, cuántas indicaciones están activas, cuánto tenés a recibir y cuánto ya recibiste.",
    "onboarding.tour.promoter.performance.title": "Tu desempeño",
    "onboarding.tour.promoter.performance.body": "El gráfico de abajo muestra la comisión generada mes a mes - en cuanto tus indicaciones se vuelvan clientes pagantes, el historial aparece acá.",
    "onboarding.tour.promoter.exploreMenu.title": "Ahora explorá el menú",
    "onboarding.tour.promoter.exploreMenu.body": "En el menú de la izquierda: tu link de indicación (Indicaciones), el extracto completo de lo que ya ganaste (Cartera) y una guía de ventas lista para usar (Portafolio de Ventas). La primera vez que abras cada una, aparece un tip rápido explicando qué es.",
    "onboarding.coach.chats.text": "Las conversaciones con huéspedes están acá. La IA responde sola las 24 horas - vos entrás solo cuando querés asumir manualmente.",
    "onboarding.coach.reservations.text": "Todas las reservas, con check-in/check-out y creación manual cuando lo necesites.",
    "onboarding.coach.roommap.text": "Vista de cada habitación/cama: ocupada, libre o esperando limpieza.",
    "onboarding.coach.opportunities.text": "Cuando un huésped pregunta por algo vendible (tour, alquiler), la IA lo detecta y lo sugiere acá - incluso indicando un socio, si vos no lo vendés.",
    "onboarding.coach.partners.text": "Portfolio de agencias socias que podés ofrecer a tus huéspedes.",
    "onboarding.coach.portfolio.text": "Lo que vendés (tours, alquileres) - esto es lo que aparece para que los hospedajes socios lo ofrezcan.",
    "onboarding.coach.guests.text": "Registro de huéspedes, con historial y documentos.",
    "onboarding.coach.operations.text": "Limpieza, mantenimiento y otras tareas del día a día del equipo.",
    "onboarding.coach.team.text": "Quién tiene acceso al sistema y qué puede ver/hacer cada persona.",
    "onboarding.coach.finance.text": "Cobros, cambio y lo que los huéspedes ya pagaron.",
    "onboarding.coach.inventory.text": "Control de ítems usados en la operación (blanquería, productos de limpieza, etc.).",
    "onboarding.coach.revenue.text": "Ingresos a lo largo del tiempo.",
    "onboarding.coach.events.text": "Espacios y eventos que organizás o alquilás.",
    "onboarding.coach.reports.text": "Números consolidados de la operación.",
    "onboarding.coach.settings.text": "Datos del hospedaje, integraciones, seguridad y más.",
    "onboarding.coach.promoter.referrals.text": "Tu link de indicación, tu franja de comisión y los hospedajes que ya indicaste - todo en esta pestaña.",
    "onboarding.coach.promoter.wallet.text": "Cuánto ya ganaste y cuánto todavía tenés a recibir, mes a mes, con el extracto completo de cada comisión.",
    "onboarding.coach.promoter.chats.text": "Conversá con quien tenga interés en StayFlow. Para usar tu propio WhatsApp/Facebook/Instagram acá, conectalo en Configuración > Comunicación.",
    "onboarding.coach.promoter.salesportfolio.text": "Una guía completa para estudiar y presentar StayFlow en cada rubro - hospedajes, agencias, locadoras e inmobiliarias.",
    "onboarding.coach.promoter.settings.text": "Conectá tus canales de conversación (WhatsApp/Facebook/Instagram) y cuidá la seguridad de tu cuenta.",
