    "onboarding.tour.default.welcome.title": "👋 Bienvenue chez StayFlow",
    "onboarding.tour.default.welcome.body": "Voici votre Dashboard - la vue d'ensemble de tout ce qui se passe en ce moment. On vous montre rapidement ce que contient chaque bloc.",
    "onboarding.tour.default.kpi.title": "Les chiffres en haut",
    "onboarding.tour.lodging.kpi.body": "Les cartes en haut affichent le taux d'occupation, les réservations et d'autres chiffres clés du jour.",
    "onboarding.tour.agency.kpi.body": "Les cartes en haut affichent un résumé rapide de votre activité aujourd'hui.",
    "onboarding.tour.default.summary.title": "Résumé exécutif",
    "onboarding.tour.default.summary.body": "Un résumé rédigé par l'IA à partir des données réelles de votre activité - pour comprendre la situation sans avoir à chercher chiffre par chiffre.",
    "onboarding.tour.lodging.opportunity.body": "Affiche les clients à fort potentiel de vente (excursion, surclassement, location), détectés automatiquement dans les conversations - pour ne pas laisser d'argent sur la table.",
    "onboarding.tour.agency.opportunity.body": "Affiche qui vous a contacté, détecté automatiquement dans les conversations - pour ne pas laisser d'argent sur la table.",
    "onboarding.tour.default.exploreMenu.title": "Explorez maintenant le menu",
    "onboarding.tour.default.exploreMenu.body": "Le menu à gauche contient chaque domaine de votre activité. La première fois que vous en ouvrez un, une astuce rapide apparaît pour l'expliquer.",
    "onboarding.tour.promoter.welcome.title": "👋 Bienvenue chez StayFlow",
    "onboarding.tour.promoter.welcome.body": "Voici votre Dashboard - le résumé de votre compte de parrain. On vous montre rapidement ce que contient chaque bloc.",
    "onboarding.tour.promoter.numbers.title": "Vos chiffres",
    "onboarding.tour.promoter.numbers.body": "Les 4 cartes en haut affichent votre palier de commission actuel, le nombre de parrainages actifs, ce que vous avez à recevoir et ce que vous avez déjà reçu.",
    "onboarding.tour.promoter.performance.title": "Votre performance",
    "onboarding.tour.promoter.performance.body": "Le graphique juste en dessous montre la commission générée mois par mois - dès que vos parrainages deviennent clients payants, l'historique apparaît ici.",
    "onboarding.tour.promoter.exploreMenu.title": "Explorez maintenant le menu",
    "onboarding.tour.promoter.exploreMenu.body": "Dans le menu à gauche : votre lien de parrainage (Parrainages), le relevé complet de vos gains (Portefeuille) et un guide de vente prêt à l'emploi (Portefeuille de Vente). La première fois que vous en ouvrez un, une astuce rapide apparaît pour l'expliquer.",
    "onboarding.coach.chats.text": "Les conversations avec les clients se trouvent ici. L'IA répond seule 24h/24 - vous n'intervenez que si vous voulez reprendre la main manuellement.",
    "onboarding.coach.reservations.text": "Toutes les réservations, avec arrivée/départ et création manuelle si besoin.",
    "onboarding.coach.roommap.text": "Vue de chaque chambre/lit : occupé, libre ou en attente de ménage.",
    "onboarding.coach.opportunities.text": "Quand un client demande quelque chose de vendable (excursion, location), l'IA le détecte et le suggère ici - allant jusqu'à recommander un partenaire si vous ne le vendez pas.",
    "onboarding.coach.partners.text": "Portefeuille d'agences partenaires que vous pouvez proposer à vos clients.",
    "onboarding.coach.portfolio.text": "Ce que vous vendez (excursions, locations) - c'est ce qui apparaît pour que les hébergements partenaires puissent le proposer.",
    "onboarding.coach.guests.text": "Registre des clients, avec historique et documents.",
    "onboarding.coach.operations.text": "Ménage, maintenance et autres tâches quotidiennes de l'équipe.",
    "onboarding.coach.team.text": "Qui a accès au système et ce que chaque personne peut voir/faire.",
    "onboarding.coach.finance.text": "Facturations, change et ce que les clients ont déjà payé.",
    "onboarding.coach.inventory.text": "Suivi des articles utilisés dans l'activité (linge, produits d'entretien, etc.).",
    "onboarding.coach.revenue.text": "Revenus dans le temps.",
    "onboarding.coach.events.text": "Espaces et événements que vous organisez ou louez.",
    "onboarding.coach.reports.text": "Chiffres consolidés de l'activité.",
    "onboarding.coach.settings.text": "Données de l'hébergement, intégrations, sécurité et plus.",
    "onboarding.coach.promoter.referrals.text": "Votre lien de parrainage, votre palier de commission et les hébergements déjà parrainés - tout dans cet onglet.",
    "onboarding.coach.promoter.wallet.text": "Ce que vous avez déjà gagné et ce qu'il vous reste à recevoir, mois par mois, avec le relevé complet de chaque commission.",
    "onboarding.coach.promoter.chats.text": "Discutez avec toute personne intéressée par StayFlow. Pour utiliser votre propre WhatsApp/Facebook/Instagram ici, connectez-le dans Paramètres > Communication.",
    "onboarding.coach.promoter.salesportfolio.text": "Un guide complet pour étudier et présenter StayFlow dans chaque secteur - hébergements, agences, loueurs et agences immobilières.",
    "onboarding.coach.promoter.settings.text": "Connectez vos canaux de discussion (WhatsApp/Facebook/Instagram) et gérez la sécurité de votre compte.",
