    "onboarding.coach.okBtn": "Verstanden",
    "onboarding.tour.default.welcome.title": "👋 Willkommen bei StayFlow",
    "onboarding.tour.default.welcome.body": "Das ist Ihr Dashboard - der Überblick über alles, was gerade passiert. Wir zeigen Ihnen kurz, was in jedem Block steckt.",
    "onboarding.tour.default.kpi.title": "Zahlen oben",
    "onboarding.tour.lodging.kpi.body": "Die Karten oben zeigen Belegung, Buchungen und andere wichtige Kennzahlen des Tages.",
    "onboarding.tour.agency.kpi.body": "Die Karten oben zeigen eine schnelle Zusammenfassung Ihres heutigen Betriebs.",
    "onboarding.tour.default.summary.title": "Management-Zusammenfassung",
    "onboarding.tour.default.summary.body": "Eine von der KI verfasste Zusammenfassung anhand der echten Daten Ihres Betriebs - damit Sie die Lage verstehen, ohne jede Zahl einzeln suchen zu müssen.",
    "onboarding.tour.lodging.opportunity.body": "Zeigt Gäste mit Verkaufspotenzial (Ausflug, Upgrade, Vermietung), automatisch aus den Gesprächen erkannt - damit Sie kein Geld liegen lassen.",
    "onboarding.tour.agency.opportunity.body": "Zeigt, wer sich bei Ihnen gemeldet hat, automatisch aus den Gesprächen erkannt - damit Sie kein Geld liegen lassen.",
    "onboarding.tour.default.exploreMenu.title": "Erkunden Sie jetzt das Menü",
    "onboarding.tour.default.exploreMenu.body": "Im Menü links finden Sie jeden Bereich Ihres Betriebs. Beim ersten Öffnen erscheint jeweils ein kurzer Tipp, der erklärt, worum es geht.",
    "onboarding.tour.promoter.welcome.title": "👋 Willkommen bei StayFlow",
    "onboarding.tour.promoter.welcome.body": "Das ist Ihr Dashboard - die Zusammenfassung Ihres Empfehlungs-Kontos. Wir zeigen Ihnen kurz, was in jedem Block steckt.",
    "onboarding.tour.promoter.numbers.title": "Ihre Zahlen",
    "onboarding.tour.promoter.numbers.body": "Die 4 Karten oben zeigen Ihre aktuelle Provisionsstufe, wie viele Empfehlungen aktiv sind, wie viel Sie noch erhalten und wie viel Sie bereits erhalten haben.",
    "onboarding.tour.promoter.performance.title": "Ihre Leistung",
    "onboarding.tour.promoter.performance.body": "Das Diagramm direkt darunter zeigt die monatlich generierte Provision - sobald Ihre Empfehlungen zu zahlenden Kunden werden, erscheint hier der Verlauf.",
    "onboarding.tour.promoter.exploreMenu.title": "Erkunden Sie jetzt das Menü",
    "onboarding.tour.promoter.exploreMenu.body": "Im Menü links: Ihr Empfehlungslink (Empfehlungen), die vollständige Abrechnung Ihrer Einnahmen (Wallet) und ein einsatzbereiter Verkaufsleitfaden (Verkaufsportfolio). Beim ersten Öffnen erscheint jeweils ein kurzer Tipp, der erklärt, worum es geht.",
    "onboarding.coach.chats.text": "Die Gästegespräche befinden sich hier. Die KI antwortet 24 Stunden selbstständig - Sie greifen nur ein, wenn Sie manuell übernehmen möchten.",
    "onboarding.coach.reservations.text": "Alle Buchungen, mit Check-in/Check-out und manueller Erstellung bei Bedarf.",
    "onboarding.coach.roommap.text": "Übersicht über jedes Zimmer/Bett: belegt, frei oder wartet auf Reinigung.",
    "onboarding.coach.opportunities.text": "Wenn ein Gast nach etwas Verkäuflichem fragt (Ausflug, Vermietung), erkennt die KI dies und schlägt es hier vor - und empfiehlt sogar einen Partner, falls Sie es nicht selbst verkaufen.",
    "onboarding.coach.partners.text": "Portfolio von Partneragenturen, die Sie Ihren Gästen anbieten können.",
    "onboarding.coach.portfolio.text": "Was Sie verkaufen (Touren, Vermietungen) - das ist es, was Partnerunterkünften zum Angebot angezeigt wird.",
    "onboarding.coach.guests.text": "Gästeregister mit Verlauf und Dokumenten.",
    "onboarding.coach.operations.text": "Reinigung, Wartung und andere tägliche Aufgaben des Teams.",
    "onboarding.coach.team.text": "Wer Zugriff auf das System hat und was jede Person sehen/tun darf.",
    "onboarding.coach.finance.text": "Abrechnungen, Wechselkurs und was Gäste bereits bezahlt haben.",
    "onboarding.coach.inventory.text": "Verwaltung der im Betrieb verwendeten Artikel (Bettwäsche, Reinigungsmittel usw.).",
    "onboarding.coach.revenue.text": "Umsatz im Zeitverlauf.",
    "onboarding.coach.events.text": "Räume und Events, die Sie organisieren oder vermieten.",
    "onboarding.coach.reports.text": "Konsolidierte Kennzahlen des Betriebs.",
    "onboarding.coach.settings.text": "Daten der Unterkunft, Integrationen, Sicherheit und mehr.",
    "onboarding.coach.promoter.referrals.text": "Ihr Empfehlungslink, Ihre Provisionsstufe und die bereits empfohlenen Unterkünfte - alles auf dieser Registerkarte.",
    "onboarding.coach.promoter.wallet.text": "Wie viel Sie bereits verdient haben und wie viel noch aussteht, Monat für Monat, mit der vollständigen Abrechnung jeder Provision.",
    "onboarding.coach.promoter.chats.text": "Chatten Sie mit allen, die sich für StayFlow interessieren. Um Ihr eigenes WhatsApp/Facebook/Instagram hier zu nutzen, verbinden Sie es unter Einstellungen > Kommunikation.",
    "onboarding.coach.promoter.salesportfolio.text": "Ein vollständiger Leitfaden, um StayFlow in jeder Branche zu studieren und zu präsentieren - Unterkünfte, Agenturen, Vermietungen und Immobilienagenturen.",
    "onboarding.coach.promoter.settings.text": "Verbinden Sie Ihre Kommunikationskanäle (WhatsApp/Facebook/Instagram) und kümmern Sie sich um die Sicherheit Ihres Kontos.",
