    "onboarding.coach.dismissLabel": "今後ヒントを表示しない",
    "onboarding.coach.okBtn": "了解",
    "onboarding.tour.default.welcome.title": "👋 StayFlowへようこそ",
    "onboarding.tour.default.welcome.body": "これがあなたのDashboardです — 今起きているすべての概要が確認できます。各ブロックの内容をさっとご紹介します。",
    "onboarding.tour.default.kpi.title": "上部の数値",
    "onboarding.tour.lodging.kpi.body": "上部のカードには、稼働率、予約件数など、その日の重要な数値が表示されます。",
    "onboarding.tour.agency.kpi.body": "上部のカードには、本日の運営状況の簡単なサマリーが表示されます。",
    "onboarding.tour.default.summary.title": "エグゼクティブサマリー",
    "onboarding.tour.default.summary.body": "実際の運営データをもとにAIが作成したサマリーです — 数値を一つずつ探さなくても、今の状況を理解できます。",
    "onboarding.tour.lodging.opportunity.body": "会話から自動検知された、販売の可能性がある宿泊客（ツアー、アップグレード、レンタル）を表示 — 機会損失を防ぎます。",
    "onboarding.tour.agency.opportunity.body": "会話から自動検知された、あなたに問い合わせてきた相手を表示 — 機会損失を防ぎます。",
    "onboarding.tour.default.exploreMenu.title": "メニューを見てみましょう",
    "onboarding.tour.default.exploreMenu.body": "左側のメニューには運営のあらゆる項目があります。それぞれを初めて開いたときに、内容を説明する簡単なヒントが表示されます。",
    "onboarding.tour.promoter.welcome.title": "👋 StayFlowへようこそ",
    "onboarding.tour.promoter.welcome.body": "これがあなたのDashboardです — 紹介パートナーアカウントの概要です。各ブロックの内容をさっとご紹介します。",
    "onboarding.tour.promoter.numbers.title": "あなたの数値",
    "onboarding.tour.promoter.numbers.body": "上部の4つのカードには、現在のコミッション率、有効な紹介数、受取予定額、受取済み額が表示されます。",
    "onboarding.tour.promoter.performance.title": "あなたの実績",
    "onboarding.tour.promoter.performance.body": "その下のグラフには月ごとに発生したコミッションが表示されます — 紹介した相手が有料顧客になり次第、ここに履歴が表示されます。",
    "onboarding.tour.promoter.exploreMenu.title": "メニューを見てみましょう",
    "onboarding.tour.promoter.exploreMenu.body": "左側のメニューには：紹介リンク（紹介）、これまでの収益の完全な明細（ウォレット）、そのまま使える営業ガイド（セールスポートフォリオ）があります。それぞれを初めて開いたときに、内容を説明する簡単なヒントが表示されます。",
    "onboarding.coach.chats.text": "宿泊客との会話はここにあります。AIが24時間自動で返信し、手動で対応を引き継ぎたいときだけあなたが入ります。",
    "onboarding.coach.reservations.text": "すべての予約をチェックイン/チェックアウトとともに管理でき、必要な時は手動で作成することもできます。",
    "onboarding.coach.roommap.text": "各部屋/ベッドの状況を確認：使用中、空室、または清掃待ち。",
    "onboarding.coach.opportunities.text": "宿泊客が販売可能なもの（ツアー、レンタルなど）を尋ねると、AIがそれを検知しここで提案します — あなたが取り扱っていない場合はパートナーを紹介することもあります。",
    "onboarding.coach.partners.text": "宿泊客に提案できる提携代理店のポートフォリオ。",
    "onboarding.coach.portfolio.text": "あなたが販売しているもの（ツアー、レンタル）— これが提携宿泊施設に提案として表示されます。",
    "onboarding.coach.guests.text": "履歴と書類を含むゲスト登録情報。",
    "onboarding.coach.operations.text": "清掃、メンテナンスなど、チームの日々の業務。",
    "onboarding.coach.team.text": "システムへのアクセス権を持つ人と、各人が閲覧・操作できる範囲。",
    "onboarding.coach.finance.text": "請求、為替、宿泊客がすでに支払った金額。",
    "onboarding.coach.inventory.text": "運営で使用する備品（リネン類、清掃用品など）の在庫管理。",
    "onboarding.coach.revenue.text": "期間ごとの収益。",
    "onboarding.coach.events.text": "主催・貸出しているスペースやイベント。",
    "onboarding.coach.reports.text": "運営の統合された数値。",
    "onboarding.coach.settings.text": "宿泊施設のデータ、連携機能、セキュリティなど。",
    "onboarding.coach.promoter.referrals.text": "紹介リンク、コミッション率、これまで紹介した宿泊施設 — すべてこのタブにあります。",
    "onboarding.coach.promoter.wallet.text": "これまでに稼いだ金額と、まだ受け取っていない金額を月ごとに確認でき、各コミッションの完全な明細も見られます。",
    "onboarding.coach.promoter.chats.text": "StayFlowに興味を持った人とここでやり取りできます。自分のWhatsApp/Facebook/Instagramを使うには、設定 > コミュニケーションで接続してください。",
    "onboarding.coach.promoter.salesportfolio.text": "宿泊施設、代理店、レンタル会社、不動産会社など、各業種でStayFlowを学び、提案するための完全ガイドです。",
    "onboarding.coach.promoter.settings.text": "会話用チャネル（WhatsApp/Facebook/Instagram）を接続し、アカウントのセキュリティを管理します。",
