    "onboarding.tour.default.welcome.title": "👋 欢迎使用StayFlow",
    "onboarding.tour.default.welcome.body": "这是您的Dashboard——当前所有情况的总览。我们来快速介绍一下每个模块里都有什么。",
    "onboarding.tour.default.kpi.title": "顶部的数据",
    "onboarding.tour.lodging.kpi.body": "顶部的卡片显示入住率、预订量以及当天其他关键数据。",
