    "onboarding.tour.lodging.opportunity.body": "显示具有销售潜力的房客（游览、升级、租赁），由对话自动检测——让您不错过任何一笔收入。",
    "onboarding.tour.agency.opportunity.body": "显示谁联系过您，由对话自动检测——让您不错过任何一笔收入。",
    "onboarding.tour.default.exploreMenu.title": "现在来看看菜单",
    "onboarding.tour.default.exploreMenu.body": "左侧菜单包含运营的各个模块。第一次打开每个模块时，都会出现一个快速提示来说明它是什么。",
    "onboarding.tour.promoter.welcome.title": "👋 欢迎使用StayFlow",
    "onboarding.tour.promoter.welcome.body": "这是您的Dashboard——您推广者账户的概要。我们来快速介绍一下每个模块里都有什么。",
    "onboarding.tour.promoter.numbers.title": "您的数据",
    "onboarding.tour.promoter.numbers.body": "顶部的4张卡片显示您当前的佣金等级、有效推荐数量、应收金额以及已收金额。",
    "onboarding.tour.promoter.performance.title": "您的业绩",
    "onboarding.tour.promoter.performance.body": "下方的图表显示逐月产生的佣金——一旦您推荐的对象成为付费客户，历史记录就会显示在这里。",
    "onboarding.tour.promoter.exploreMenu.title": "现在来看看菜单",
    "onboarding.tour.promoter.exploreMenu.body": "左侧菜单中有：您的推荐链接（推荐）、您已赚取金额的完整明细（钱包），以及一份可直接使用的销售指南（销售资料）。第一次打开每个模块时，都会出现一个快速提示来说明它是什么。",
    "onboarding.coach.chats.text": "与房客的对话都在这里。AI会全天24小时自动回复——只有当您想手动接管时才需要介入。",
    "onboarding.coach.reservations.text": "所有预订，包含入住/退房，以及需要时的手动创建。",
    "onboarding.coach.roommap.text": "查看每个房间/床位的状态：已入住、空闲或待清洁。",
    "onboarding.coach.opportunities.text": "当房客询问可销售的项目（游览、租赁）时，AI会检测到并在此提出建议——如果您不销售该项目，甚至会推荐一个合作伙伴。",
    "onboarding.coach.partners.text": "可以推荐给房客的合作旅行社目录。",
    "onboarding.coach.portfolio.text": "您所销售的产品（游览、租赁）——这些会显示给合作住宿以供推荐。",
    "onboarding.coach.guests.text": "房客档案，包含历史记录与证件。",
    "onboarding.coach.operations.text": "清洁、维护及团队其他日常任务。",
    "onboarding.coach.team.text": "谁拥有系统访问权限，以及每个人可以查看/操作的内容。",
    "onboarding.coach.finance.text": "收费、汇率以及房客已支付的款项。",
    "onboarding.coach.inventory.text": "运营所用物品的库存管理（床品、清洁用品等）。",
    "onboarding.coach.revenue.text": "随时间变化的收入。",
    "onboarding.coach.events.text": "您组织或出租的场地和活动。",
    "onboarding.coach.reports.text": "运营的汇总数据。",
    "onboarding.coach.settings.text": "住宿资料、集成、安全等设置。",
    "onboarding.coach.promoter.referrals.text": "您的推荐链接、佣金等级以及您已推荐的住宿——全部都在这个标签页里。",
    "onboarding.coach.promoter.wallet.text": "逐月查看您已赚取的金额和仍应收的金额，并附有每笔佣金的完整明细。",
    "onboarding.coach.promoter.chats.text": "在这里与对StayFlow感兴趣的人聊天。要使用您自己的WhatsApp/Facebook/Instagram，请在设置>通讯中进行连接。",
    "onboarding.coach.promoter.salesportfolio.text": "一份完整的指南，帮助您学习并向各行业介绍StayFlow——住宿、旅行社、租赁公司和房地产中介。",
    "onboarding.coach.promoter.settings.text": "连接您的沟通渠道（WhatsApp/Facebook/Instagram）并管理账户安全。",
