    "onboarding.coach.dismissLabel": "Больше не показывать подсказки",
    "onboarding.coach.okBtn": "Понятно",
    "onboarding.tour.default.welcome.title": "👋 Добро пожаловать в StayFlow",
    "onboarding.tour.default.welcome.body": "Это ваш Dashboard — обзор всего, что происходит прямо сейчас. Быстро покажем, что есть в каждом блоке.",
    "onboarding.tour.default.kpi.title": "Цифры сверху",
    "onboarding.tour.lodging.kpi.body": "Карточки сверху показывают загрузку, бронирования и другие ключевые цифры дня.",
    "onboarding.tour.agency.kpi.body": "Карточки сверху показывают краткую сводку по сегодняшней работе.",
    "onboarding.tour.default.summary.title": "Краткая сводка",
    "onboarding.tour.default.summary.body": "Сводка, написанная ИИ на основе реальных данных вашей работы, - чтобы понять ситуацию, не выискивая цифры по одной.",
    "onboarding.tour.lodging.opportunity.body": "Показывает гостей с потенциалом продажи (экскурсия, апгрейд, аренда), автоматически определённых по переписке - чтобы вы не теряли деньги.",
    "onboarding.tour.agency.opportunity.body": "Показывает, кто к вам обратился, автоматически определённых по переписке - чтобы вы не теряли деньги.",
    "onboarding.tour.default.exploreMenu.title": "Теперь изучите меню",
    "onboarding.tour.default.exploreMenu.body": "В меню слева есть каждая область вашей работы. При первом открытии каждого раздела появляется краткая подсказка с объяснением.",
    "onboarding.tour.promoter.welcome.title": "👋 Добро пожаловать в StayFlow",
    "onboarding.tour.promoter.welcome.body": "Это ваш Dashboard — сводка по вашему аккаунту промоутера. Быстро покажем, что есть в каждом блоке.",
    "onboarding.tour.promoter.numbers.title": "Ваши цифры",
    "onboarding.tour.promoter.numbers.body": "4 карточки сверху показывают ваш текущий уровень комиссии, число активных рефералов, сколько вам причитается и сколько уже получено.",
    "onboarding.tour.promoter.performance.title": "Ваши результаты",
    "onboarding.tour.promoter.performance.body": "График ниже показывает комиссию по месяцам - как только ваши рефералы станут платящими клиентами, здесь появится история.",
    "onboarding.tour.promoter.exploreMenu.title": "Теперь изучите меню",
    "onboarding.tour.promoter.exploreMenu.body": "В меню слева: ваша реферальная ссылка (Рефералы), полная выписка того, что вы заработали (Кошелёк), и готовое руководство по продажам (Портфолио продаж). При первом открытии каждого раздела появляется краткая подсказка с объяснением.",
    "onboarding.coach.chats.text": "Здесь находятся переписки с гостями. ИИ отвечает самостоятельно 24 часа - вы вмешиваетесь, только если хотите взять разговор вручную.",
    "onboarding.coach.reservations.text": "Все бронирования с заездом/выездом и возможностью создать вручную при необходимости.",
    "onboarding.coach.roommap.text": "Обзор каждого номера/кровати: занят, свободен или ожидает уборки.",
    "onboarding.coach.opportunities.text": "Когда гость спрашивает о чём-то, что можно продать (экскурсия, аренда), ИИ обнаруживает это и предлагает здесь - вплоть до рекомендации партнёра, если вы это не продаёте.",
    "onboarding.coach.partners.text": "Портфолио партнёрских агентств, которые вы можете предложить своим гостям.",
    "onboarding.coach.portfolio.text": "То, что вы продаёте (экскурсии, аренда) - именно это отображается для партнёрских объектов размещения.",
    "onboarding.coach.guests.text": "Реестр гостей с историей и документами.",
    "onboarding.coach.operations.text": "Уборка, обслуживание и другие повседневные задачи команды.",
    "onboarding.coach.team.text": "У кого есть доступ к системе и что может видеть/делать каждый.",
    "onboarding.coach.finance.text": "Начисления, обменный курс и то, что гости уже оплатили.",
    "onboarding.coach.inventory.text": "Учёт предметов, используемых в работе (бельё, чистящие средства и т.д.).",
    "onboarding.coach.revenue.text": "Доход за период.",
    "onboarding.coach.events.text": "Пространства и мероприятия, которые вы организуете или сдаёте.",
    "onboarding.coach.reports.text": "Сводные показатели по работе.",
    "onboarding.coach.settings.text": "Данные объекта, интеграции, безопасность и многое другое.",
    "onboarding.coach.promoter.referrals.text": "Ваша реферальная ссылка, уровень комиссии и уже рекомендованные объекты - всё на этой вкладке.",
    "onboarding.coach.promoter.wallet.text": "Сколько вы уже заработали и сколько ещё получите, по месяцам, с полной выпиской по каждой комиссии.",
    "onboarding.coach.promoter.chats.text": "Общайтесь с теми, кто заинтересовался StayFlow. Чтобы использовать здесь свой WhatsApp/Facebook/Instagram, подключите его в Настройках > Связь.",
    "onboarding.coach.promoter.salesportfolio.text": "Полное руководство для изучения и презентации StayFlow в каждой отрасли - объекты размещения, агентства, прокатные компании и агентства недвижимости.",
    "onboarding.coach.promoter.settings.text": "Подключите свои каналы общения (WhatsApp/Facebook/Instagram) и позаботьтесь о безопасности своей учётной записи.",
