    "onboarding.tour.default.welcome.title": "👋 Welkom bij StayFlow",
    "onboarding.tour.default.welcome.body": "Dit is uw Dashboard - het overzicht van alles wat er nu gebeurt. We laten u snel zien wat er in elk blok staat.",
    "onboarding.tour.default.kpi.title": "Cijfers bovenaan",
    "onboarding.tour.lodging.kpi.body": "De kaarten bovenaan tonen bezetting, boekingen en andere belangrijke cijfers van de dag.",
    "onboarding.tour.agency.kpi.body": "De kaarten bovenaan tonen een snel overzicht van uw activiteit van vandaag.",
    "onboarding.tour.default.summary.title": "Managementsamenvatting",
    "onboarding.tour.default.summary.body": "Een samenvatting geschreven door de AI, gebaseerd op de echte gegevens van uw activiteit - zodat u de situatie begrijpt zonder cijfer voor cijfer te hoeven uitzoeken.",
    "onboarding.tour.lodging.opportunity.body": "Toont gasten met verkooppotentieel (excursie, upgrade, verhuur), automatisch gedetecteerd uit de gesprekken - zodat u geen geld laat liggen.",
    "onboarding.tour.agency.opportunity.body": "Toont wie contact met u heeft opgenomen, automatisch gedetecteerd uit de gesprekken - zodat u geen geld laat liggen.",
    "onboarding.tour.default.exploreMenu.title": "Verken nu het menu",
    "onboarding.tour.default.exploreMenu.body": "In het menu links vindt u elk onderdeel van uw activiteit. De eerste keer dat u er een opent, verschijnt een korte tip die uitlegt wat het is.",
    "onboarding.tour.promoter.welcome.title": "👋 Welkom bij StayFlow",
    "onboarding.tour.promoter.welcome.body": "Dit is uw Dashboard - het overzicht van uw promotor-account. We laten u snel zien wat er in elk blok staat.",
    "onboarding.tour.promoter.numbers.title": "Uw cijfers",
    "onboarding.tour.promoter.numbers.body": "De 4 kaarten bovenaan tonen uw huidige commissieniveau, hoeveel verwijzingen actief zijn, hoeveel u nog ontvangt en hoeveel u al heeft ontvangen.",
    "onboarding.tour.promoter.performance.title": "Uw prestaties",
    "onboarding.tour.promoter.performance.body": "De grafiek hieronder toont de gegenereerde commissie per maand - zodra uw verwijzingen betalende klanten worden, verschijnt de geschiedenis hier.",
    "onboarding.tour.promoter.exploreMenu.title": "Verken nu het menu",
    "onboarding.tour.promoter.exploreMenu.body": "In het menu links: uw verwijzingslink (Verwijzingen), het volledige overzicht van wat u al heeft verdiend (Portemonnee) en een kant-en-klare verkoopgids (Verkoopportfolio). De eerste keer dat u er een opent, verschijnt een korte tip die uitlegt wat het is.",
    "onboarding.coach.chats.text": "De gesprekken met gasten staan hier. De AI antwoordt zelfstandig 24 uur per dag - u grijpt alleen in wanneer u het handmatig wilt overnemen.",
    "onboarding.coach.reservations.text": "Alle boekingen, met in-/uitchecken en handmatige aanmaak wanneer nodig.",
    "onboarding.coach.roommap.text": "Overzicht van elke kamer/bed: bezet, vrij of wachtend op schoonmaak.",
    "onboarding.coach.opportunities.text": "Wanneer een gast vraagt naar iets verkoopbaars (excursie, verhuur), detecteert de AI dit en stelt het hier voor - en beveelt zelfs een partner aan als u het zelf niet verkoopt.",
    "onboarding.coach.partners.text": "Portfolio van partnerbureaus die u aan uw gasten kunt aanbieden.",
    "onboarding.coach.portfolio.text": "Wat u verkoopt (excursies, verhuur) - dit is wat verschijnt zodat partneraccommodaties het kunnen aanbieden.",
    "onboarding.coach.guests.text": "Gastenregister, met geschiedenis en documenten.",
    "onboarding.coach.operations.text": "Schoonmaak, onderhoud en andere dagelijkse taken van het team.",
    "onboarding.coach.team.text": "Wie toegang heeft tot het systeem en wat elke persoon mag zien/doen.",
    "onboarding.coach.finance.text": "Facturaties, wisselkoers en wat gasten al hebben betaald.",
    "onboarding.coach.inventory.text": "Beheer van items die in de operatie worden gebruikt (linnengoed, schoonmaakproducten, enz.).",
    "onboarding.coach.revenue.text": "Omzet in de tijd.",
    "onboarding.coach.events.text": "Ruimtes en evenementen die u organiseert of verhuurt.",
    "onboarding.coach.reports.text": "Geconsolideerde cijfers van de activiteit.",
    "onboarding.coach.settings.text": "Gegevens van de accommodatie, integraties, beveiliging en meer.",
    "onboarding.coach.promoter.referrals.text": "Uw verwijzingslink, uw commissieniveau en de accommodaties die u al heeft verwezen - alles in dit tabblad.",
    "onboarding.coach.promoter.wallet.text": "Hoeveel u al heeft verdiend en hoeveel u nog ontvangt, maand voor maand, met het volledige overzicht van elke commissie.",
    "onboarding.coach.promoter.chats.text": "Chat met iedereen die geïnteresseerd is in StayFlow. Om hier uw eigen WhatsApp/Facebook/Instagram te gebruiken, verbindt u dit in Instellingen > Communicatie.",
    "onboarding.coach.promoter.salesportfolio.text": "Een complete gids om StayFlow te bestuderen en te presenteren in elke sector - accommodaties, bureaus, verhuurbedrijven en makelaars.",
    "onboarding.coach.promoter.settings.text": "Verbind uw gespreks kanalen (WhatsApp/Facebook/Instagram) en zorg voor de beveiliging van uw account.",
